display.text:
name: test-srsim

"on":
  issue_comment:
    types: [created]

jobs:
  authorize:
    if: >-
      github.event.issue.pull_request &&
      contains(github.event.comment.body, '/test srsim')
    runs-on: ubuntu-24.04
    permissions:
      contents: read
      issues: write
      pull-requests: read
    outputs:
      authorized: ${{ steps.authorize.outputs.authorized }}
      head_sha: ${{ steps.authorize.outputs.head_sha }}
      test_ref: ${{ steps.authorize.outputs.test_ref }}
    steps:
      - name: Verify command and permissions
        id: authorize
        uses: actions/github-script@v9
        with:
          script: |
            const command = context.payload.comment.body.trim();
            if (command !== '/test srsim') {
              core.setOutput('authorized', 'false');
              return;
            }

            let authorized = false;
            try {
              const { data } = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                username: context.payload.comment.user.login,
              });
              authorized =
                ['admin', 'maintain'].includes(data.role_name) ||
                data.permissions?.admin === true ||
                data.permissions?.maintain === true;
            } catch (error) {
              if (error.status !== 404) throw error;
            }

            core.setOutput('authorized', String(authorized));

            if (!authorized) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: 'Only repository maintainers can run `/test srsim`.',
              });
              return;
            }

            const { data: pullRequest } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number,
            });
            core.setOutput('head_sha', pullRequest.head.sha);
            core.setOutput('test_ref', pullRequest.merge_commit_sha || pullRequest.head.sha);

  create-check:
    needs: authorize
    if: needs.authorize.outputs.authorized == 'true'
    runs-on: ubuntu-24.04
    permissions:
      checks: write
    outputs:
      check_run_id: ${{ steps.create.outputs.check_run_id }}
    steps:
      - name: Create PR check
        id: create
        uses: actions/github-script@v9
        env:
          HEAD_SHA: ${{ needs.authorize.outputs.head_sha }}
        with:
          script: |
            const { data: checkRun } = await github.rest.checks.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              name: 'srsim-tests (manual)',
              head_sha: process.env.HEAD_SHA,
              status: 'in_progress',
              details_url: `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`,
              external_id: String(context.runId),
              output: {
                title: 'srsim tests are running',
                summary: 'Triggered by `/test srsim`.',
              },
            });
            core.setOutput('check_run_id', String(checkRun.id));

  load-vars:
    needs: authorize
    if: needs.authorize.outputs.authorized == 'true'
    runs-on: ubuntu-24.04
    outputs:
      go_ver: ${{ steps.vars.outputs.go_ver }}
      py_ver: ${{ steps.vars.outputs.py_ver }}
      uv_ver: ${{ steps.vars.outputs.uv_ver }}
    steps:
      - uses: actions/checkout@v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          sparse-checkout: .github/vars.env
          sparse-checkout-cone-mode: false
          persist-credentials: false
      - id: vars
        run: |
          source .github/vars.env
          echo "go_ver=$GO_VER" >> "$GITHUB_OUTPUT"
          echo "py_ver=$PY_VER" >> "$GITHUB_OUTPUT"
          echo "uv_ver=$UV_VER" >> "$GITHUB_OUTPUT"

  build-containerlab:
    needs:
      - authorize
      - create-check
      - load-vars
    if: needs.authorize.outputs.authorized == 'true'
    strategy:
      matrix:
        include:
          - runner: ubuntu-24.04
            arch: amd64
          - runner: ubuntu-24.04-arm
            arch: arm64
    uses: ./.github/workflows/build-containerlab.yml
    permissions:
      contents: read
      actions: read
      packages: read
    with:
      go_ver: ${{ needs.load-vars.outputs.go_ver }}
      runner: ${{ matrix.runner }}
      arch: ${{ matrix.arch }}
      ref: ${{ needs.authorize.outputs.test_ref }}

  srsim-tests:
    needs:
      - authorize
      - create-check
      - load-vars
      - build-containerlab
    if: needs.authorize.outputs.authorized == 'true'
    uses: ./.github/workflows/srsim-tests.yml
    permissions:
      contents: read
      actions: read
      packages: read
    secrets:
      SRSIM_LICENSE: ${{ secrets.SRSIM_LICENSE }}
    with:
      py_ver: ${{ needs.load-vars.outputs.py_ver }}
      uv_ver: ${{ needs.load-vars.outputs.uv_ver }}
      ref: ${{ needs.authorize.outputs.test_ref }}

  report:
    needs:
      - create-check
      - build-containerlab
      - srsim-tests
    if: always() && needs.create-check.result == 'success'
    runs-on: ubuntu-24.04
    permissions:
      checks: write
    steps:
      - name: Update PR check
        uses: actions/github-script@v9
        env:
          CHECK_RUN_ID: ${{ needs.create-check.outputs.check_run_id }}
          BUILD_RESULT: ${{ needs.build-containerlab.result }}
          TEST_RESULT: ${{ needs.srsim-tests.result }}
        with:
          script: |
            const conclusions = {
              success: 'success',
              failure: 'failure',
              cancelled: 'cancelled',
              skipped: 'neutral',
            };
            const result =
              ['failure', 'cancelled'].includes(process.env.BUILD_RESULT)
                ? process.env.BUILD_RESULT
                : process.env.TEST_RESULT;
            const conclusion = conclusions[result] || 'failure';
            await github.rest.checks.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              check_run_id: Number(process.env.CHECK_RUN_ID),
              status: 'completed',
              conclusion,
              output: {
                title: `srsim tests ${result}`,
                summary: `The manual srsim test workflow finished with result: ${result}.`,
              },
            });
